import math
from enum import Enum
from dataclasses import dataclass
from abc import ABC, abstractmethod
from typing import Optional, NamedTuple, Dict, Type


# --- Fitting Type Enum and Lookup ---

class FittingType(Enum):
    HORIZONTAL_BEND = "Horizontal Bend"
    VERTICAL_BEND = "Vertical Bend"
    TEE = "Tee"
    ANGLE_BRANCH = "Angle Branch"
    CLOSED_VALVE = "Closed Valve"
    BLANK_END = "Blank End"
    TAPER_THRUST = "Taper Thrust"

FITTING_TYPE_LOOKUP: Dict[str, FittingType] = {ft.value.lower(): ft for ft in FittingType}

def get_fitting_type(user_input: str) -> FittingType:
    normalized = user_input.strip().lower()
    try:
        return FITTING_TYPE_LOOKUP[normalized]
    except KeyError:
        raise ValueError(f"Unknown fitting type: {user_input}")


# --- Abstract Base Class ---

@dataclass
class Fitting(ABC):
    maximum_design_pressure: float
    depth_crown: float

    @abstractmethod
    def head_loss(self, flow_rate: float, k_factor: float = 0.5) -> float:
        ...

    @property
    @abstractmethod
    def thrust_force_resultant(self) -> float:
        ...

# --- Fitting Dataclasses ---

@dataclass
class HorizontalBend(Fitting):
    diameter_outside: float
    angle: float      # degrees
    radius: float = 0   # meters

    def head_loss(self, flow_rate: float, k_factor: float = 0.5) -> float:
        area = math.pi * (self.diameter_outside / 2) ** 2
        velocity = flow_rate / area
        return k_factor * (velocity ** 2) / (2 * 9.81)

    @property
    def thrust_force_resultant(self) -> float:
        area = math.pi * self.diameter_outside ** 2 / 4
        return 2 * self.maximum_design_pressure * area * math.sin(math.radians(self.angle) / 2)

    @property
    def thrust_force_x_component(self) -> float:
        area = math.pi * self.diameter_outside ** 2 / 4
        return self.maximum_design_pressure * area * (1 - math.cos(math.radians(self.angle)))

    @property
    def thrust_force_y_component(self) -> float:
        area = math.pi * self.diameter_outside ** 2 / 4
        return self.maximum_design_pressure * area * math.sin(math.radians(self.angle))


@dataclass
class VerticalBend(Fitting):
    diameter_outside: float
    angle: float      # degrees
    radius: float     # meters

    def head_loss(self, flow_rate: float, k_factor: float = 0.5) -> float:
        area = math.pi * (self.diameter_outside / 2) ** 2
        velocity = flow_rate / area
        return k_factor * (velocity ** 2) / (2 * 9.81)

    @property
    def thrust_force_resultant(self) -> float:
        area = math.pi * self.diameter_outside ** 2 / 4
        return 2 * self.maximum_design_pressure * area * math.sin(math.radians(self.angle) / 2)

    @property
    def thrust_force_horizontal(self) -> float:
        area = math.pi * self.diameter_outside ** 2 / 4
        return self.maximum_design_pressure * area * (1 - math.cos(math.radians(self.angle)))

    @property
    def thrust_force_vertical(self) -> float:
        area = math.pi * self.diameter_outside ** 2 / 4
        return self.maximum_design_pressure * area * math.sin(math.radians(self.angle))


@dataclass
class Tee(Fitting):
    diameter_outside_main: float
    diameter_outside_branch: float

    def head_loss(self, flow_rate: float, k_factor: float = 0.5) -> float:
        area = math.pi * (self.diameter_outside_branch / 2) ** 2
        velocity = flow_rate / area
        return k_factor * (velocity ** 2) / (2 * 9.81)

    @property
    def thrust_force_resultant(self) -> float:
        area_branch = math.pi * self.diameter_outside_branch ** 2 / 4
        return self.maximum_design_pressure * area_branch


@dataclass
class AngleBranch(Fitting):
    angle: float
    diameter_outside_main: float
    diameter_outside_branch: float

    def head_loss(self, flow_rate: float, k_factor: float = 0.5) -> float:
        area = math.pi * (self.diameter_outside_branch / 2) ** 2
        velocity = flow_rate / area
        return k_factor * (velocity ** 2) / (2 * 9.81)

    @property
    def thrust_force_x_component(self) -> float:
        area_branch = math.pi * self.diameter_outside_branch ** 2 / 4
        return self.maximum_design_pressure * area_branch


@dataclass
class ClosedValve(Fitting):
    diameter_outside: float

    def head_loss(self, flow_rate: float, k_factor: float = 0.5) -> float:
        area = math.pi * (self.diameter_outside / 2) ** 2
        velocity = flow_rate / area
        return k_factor * (velocity ** 2) / (2 * 9.81)

    @property
    def thrust_force_resultant(self) -> float:
        area = math.pi * self.diameter_outside ** 2 / 4
        return self.maximum_design_pressure * area


@dataclass
class BlankEnd(Fitting):
    diameter_outside: float

    def head_loss(self, flow_rate: float, k_factor: float = 0.5) -> float:
        area = math.pi * (self.diameter_outside / 2) ** 2
        velocity = flow_rate / area
        return k_factor * (velocity ** 2) / (2 * 9.81)

    @property
    def thrust_force_resultant(self) -> float:
        area = math.pi * self.diameter_outside ** 2 / 4
        return self.maximum_design_pressure * area


@dataclass
class TaperThrust(Fitting):
    diameter_outside_large: float
    diameter_outside_small: float

    def head_loss(self, flow_rate: float, k_factor: float = 0.5) -> float:
        average_diameter = (self.diameter_outside_large + self.diameter_outside_small) / 2
        area = math.pi * (average_diameter / 2) ** 2
        velocity = flow_rate / area
        return k_factor * (velocity ** 2) / (2 * 9.81)

    @property
    def thrust_force_resultant(self) -> float:
        area_large = math.pi * self.diameter_outside_large ** 2 / 4
        area_small = math.pi * self.diameter_outside_small ** 2 / 4
        return self.maximum_design_pressure * (area_large - area_small)


# --- Factory and Dispatcher ---

FITTING_CLASS_MAP: Dict[FittingType, Type[Fitting]] = {
    FittingType.HORIZONTAL_BEND: HorizontalBend,
    FittingType.VERTICAL_BEND: VerticalBend,
    FittingType.TEE: Tee,
    FittingType.ANGLE_BRANCH: AngleBranch,
    FittingType.CLOSED_VALVE: ClosedValve,
    FittingType.BLANK_END: BlankEnd,
    FittingType.TAPER_THRUST: TaperThrust,
}

def create_fitting(fitting_type: FittingType, maximum_design_pressure, depth_crown, **kwargs) -> Fitting:
    cls = FITTING_CLASS_MAP.get(fitting_type)
    if not cls:
        raise ValueError(f"Unknown fitting type: {fitting_type}")
    return cls(maximum_design_pressure, depth_crown, **kwargs)


class ThrustForceResult(NamedTuple):
    resultant: Optional[float] = None
    x_component: Optional[float] = None
    y_component: Optional[float] = None
    horizontal_component: Optional[float] = None
    vertical_component: Optional[float] = None


def thrust_force(fitting: Fitting) -> ThrustForceResult:
    """
    Calculate thrust force values for a fitting.
    Returns a ThrustForceResult with relevant components populated.
    """
    result = {}

    if hasattr(fitting, "thrust_force_resultant"):
        result["resultant"] = getattr(fitting, "thrust_force_resultant")
    if hasattr(fitting, "thrust_force_x_component"):
        result["x_component"] = getattr(fitting, "thrust_force_x_component")
    if hasattr(fitting, "thrust_force_y_component"):
        result["y_component"] = getattr(fitting, "thrust_force_y_component")
    if hasattr(fitting, "thrust_force_horizontal"):
        result["horizontal_component"] = getattr(fitting, "thrust_force_horizontal")
    if hasattr(fitting, "thrust_force_vertical"):
        result["vertical_component"] = getattr(fitting, "thrust_force_vertical")

    return ThrustForceResult(**result)

