def get_fitting_parameters(fitting_type_str: str) -> dict:
    """
    Returns a dictionary where keys are parameter names and values are prompt strings,
    for the specified fitting type.
    """
    fitting_enum = get_fitting_type(fitting_type_str)
    params = FITTING_PARAMS[fitting_enum]
    param_dict = {param_name: prompt for param_name, prompt in params}
    return param_dict

